check_numeric_finite <- function(
    x,
    object_name
) {
  
  if (!is.numeric(x)) {
    
    stop(
      object_name,
      " must be numeric."
    )
  }
  
  if (any(!is.finite(x))) {
    
    stop(
      object_name,
      " contains NA, NaN, or Inf values."
    )
  }
  
  invisible(TRUE)
}

