###############################################################
# 18. POSITIONAL ENCODING
###############################################################
#
# Standard sinusoidal positional encoding:
#
#   PE(pos, 2i)   = sin(pos / 10000^(2i/d))
#   PE(pos, 2i+1) = cos(pos / 10000^(2i/d))
#
# The resulting matrix has dimension:
#
#   sequence_length x attention_dim
#
###############################################################

positional_encoding <- function(
    sequence_length,
    d_model
) {
  
  if (sequence_length < 1L) {
    
    stop(
      "sequence_length must be positive."
    )
  }
  
  if (d_model < 2L) {
    
    stop(
      "d_model must be at least 2."
    )
  }
  
  position <- matrix(
    rep(
      0:(sequence_length - 1L),
      d_model
    ),
    nrow = sequence_length,
    ncol = d_model
  )
  
  even_index <- seq(
    0L,
    d_model - 1L,
    by = 2L
  )
  
  odd_index <- seq(
    1L,
    d_model - 1L,
    by = 2L
  )
  
  div_term <- exp(
    even_index *
      (
        -log(10000) /
          d_model
      )
  )
  
  PE <- matrix(
    0,
    nrow = sequence_length,
    ncol = d_model
  )
  
  PE[
    ,
    even_index + 1L
  ] <-
    sin(
      position[
        ,
        even_index + 1L
      ] *
        rep(
          div_term,
          each = sequence_length
        )
    )
  
  if (length(odd_index) > 0L) {
    
    PE[
      ,
      odd_index + 1L
    ] <-
      cos(
        position[
          ,
          odd_index + 1L
        ] *
          rep(
            div_term[
              seq_along(odd_index)
            ],
            each = sequence_length
          )
      )
  }
  
  PE
}

###############################################################
# 19. CREATE POSITIONAL ENCODING
###############################################################

PE_matrix <-
