###############################################################
# 21. TRANSFORMER ENCODER BLOCK
###############################################################

transformer_block <- function(
    
  inputs,
  
  attention_dim,
  
  head_size = 16L,
  
  num_heads = 4L,
  
  ff_dim = 128L,
  
  dropout = 0.10,
  
  block_id = 1L
  
) {
  
  ###########################################################
  # Multi-Head Self-Attention
  ###########################################################
  
  attention_layer <-
    layer_multi_head_attention(
      
      num_heads =
        num_heads,
      
      key_dim =
        head_size,
      
      dropout =
        dropout,
      
      name =
        paste0(
          "SelfAttention_",
          block_id
        )
    )
  
  attention <-
    attention_layer(
      query = inputs,
      key = inputs,
      value = inputs
    )
  
  ###########################################################
  # Attention Dropout
  ###########################################################
  
  attention <-
    layer_dropout(
      rate = dropout,
      name =
        paste0(
          "AttentionDropout_",
          block_id
        )
    )(
      attention
    )
  
  ###########################################################
  # First Residual Connection
  ###########################################################
  
  x <-
    layer_add(
      list(
        inputs,
        attention
      ),
      name =
        paste0(
          "AttentionResidual_",
          block_id
        )
    )
  
  ###########################################################
  # First Layer Normalization
  ###########################################################
  
  x <-
    layer_layer_normalization(
      epsilon = 1e-6,
      name =
        paste0(
          "AttentionNorm_",
          block_id
        )
    )(
      x
    )
  
  ###########################################################
  # Feed-Forward Network
  ###########################################################
  
  ff <-
    x %>%
    
    layer_dense(
      units = ff_dim,
      activation = "relu",
      name =
        paste0(
          "FFN_Dense1_",
          block_id
        )
    ) %>%
    
    layer_dropout(
      rate = dropout,
      name =
        paste0(
          "FFN_Dropout_",
          block_id
        )
    ) %>%
    
    layer_dense(
      units = attention_dim,
      name =
        paste0(
          "FFN_Dense2_",
          block_id
        )
    )
  
  ###########################################################
  # Second Residual Connection
  ###########################################################
  
  x <-
    layer_add(
      list(
        x,
        ff
      ),
      name =
        paste0(
          "FFNResidual_",
          block_id
        )
    )
  
  ###########################################################
  # Second Layer Normalization
  ###########################################################
  
  outputs <-
    layer_layer_normalization(
      epsilon = 1e-6,
      name =
        paste0(
          "FFNNorm_",
          block_id
        )
    )(
      x
    )
  
  outputs
}

###############################################################
# 22. BUILD TRANSFORMER ENCODER
###############################################################

build_transformer_encoder <- function(
    
  sequence_length,
  
  feature_dim,
  
  attention_dim,
  
  head_size = 16L,
  
  num_heads = 4L,
  
  ff_dim = 128L,
  
  dropout = 0.10,
  
  num_blocks = 2L
  
) {
  
  ###########################################################
  # Input
  ###########################################################
  
  inputs <-
    layer_input(
      
      shape =
        c(
          sequence_length,
          feature_dim
        ),
      
      name =
        "InputSequence"
    )
  
  ###########################################################
  # Input Projection
  ###########################################################
  
  x <-
    inputs %>%
    
    layer_dense(
      
      units =
        attention_dim,
      
      name =
        "FeatureProjection"
    )
  
  ###########################################################
  # Sinusoidal Positional Encoding
  ###########################################################
  #
  # PE_tensor has shape:
  #
  #   sequence_length x attention_dim
  #
  # TensorFlow broadcasts it across the batch dimension.
  #
  ###########################################################
  
  x <-
    layer_lambda(
      
      f = function(z) {
        
        z + PE_tensor
        
      },
      
      name =
        "PositionalEncoding"
    )(
      x
    )
  
  ###########################################################
  # Transformer Encoder Blocks
  ###########################################################
  
  for (b in seq_len(num_blocks)) {
    
    x <-
      transformer_block(
        
        inputs =
          x,
        
        attention_dim =
          attention_dim,
        
        head_size =
          head_size,
        
        num_heads =
          num_heads,
        
        ff_dim =
          ff_dim,
        
        dropout =
          dropout,
        
        block_id =
          b
      )
  }
  
  ###########################################################
  # Encoder Model
  ###########################################################
  
  keras_model(
    
    inputs =
      inputs,
    
    outputs =
      x,
    
    name =
      "TransformerEncoder"
  )
}

###############################################################
# 23. BUILD MODEL
###############################################################

encoder <-
