X_test_batch <-
  array(
    as.numeric(X_test_batch),
    dim =
      dim(X_test_batch)
  )

if (any(!is.finite(X_test_batch))) {
  
  stop(
    "Forward-pass test batch contains non-finite values."
  )
}

###############################################################
# 28. FORWARD PASS
###############################################################

test_output <-
  encoder(
    X_test_batch,
    training = FALSE
  )

###############################################################
# 29. OUTPUT SHAPE
###############################################################

output_shape <-
  dim(
    test_output
  )

cat(
  "Forward-pass output shape:\n"
)

print(
  output_shape
)

###############################################################
# 30. OUTPUT DIMENSION VALIDATION
###############################################################

expected_output_dim <-
  c(
    test_batch_size,
    sequence_length,
    attention_dim
  )

if (!identical(
  as.integer(output_shape),
  as.integer(expected_output_dim)
)) {
  
  stop(
    paste0(
      "Unexpected Transformer output shape.\n",
      "Expected: ",
      paste(
        expected_output_dim,
        collapse = " x "
      ),
      "\nObserved: ",
      paste(
        output_shape,
        collapse = " x "
      )
    )
  )
}

###############################################################
# 31. OUTPUT FINITE CHECK
###############################################################

test_output_array <-
  as.array(
    test_output
  )

if (any(!is.finite(test_output_array))) {
  
  stop(
    "Transformer forward pass produced non-finite values."
  )
}

cat(
  "Forward pass successful.\n"
)

cat(
  "Output dimension: ",
  paste(
    output_shape,
    collapse = " x "
  ),
  "\n",
  sep = ""
)

###############################################################
# 32. MODEL PARAMETER COUNT
###############################################################

parameter_count <-
  tryCatch(
    
    as.numeric(
      encoder$count_params()
    ),
    
    error = function(e) {
      
      NA_real_
      
    }
  )

###############################################################
# 33. SAVE KERAS 3 MODEL
###############################################################

cat("\n")
cat(
  "Saving Transformer model to:\n"
)

cat(
  MODEL_FILE,
  "\n"
)

save_model(
  encoder,
  MODEL_FILE,
  overwrite = TRUE
)

###############################################################
# 34. VERIFY MODEL FILE
###############################################################

if (!file.exists(MODEL_FILE)) {
  
  stop(
    "Transformer model was not saved successfully."
  )
}

model_size <-
  file.info(
    MODEL_FILE
  )$size

if (
  is.na(model_size) ||
  model_size <= 0
) {
  
  stop(
    "Transformer model file is empty."
  )
}

cat(
  "Model saved successfully.\n"
)

cat(
  "Model file size: ",
  round(
    model_size / 1024^2,
    3
  ),
  " MB\n",
  sep = ""
)

###############################################################
# 35. SAVE MODEL CONFIGURATION
###############################################################

TransformerConfig <- list(
  
  model_name =
    "TransformerEncoder",
  
  sequence_length =
    sequence_length,
  
  feature_dim =
    feature_dim,
  
  attention_dim =
    attention_dim,
  
  head_size =
    head_size,
  
  num_heads =
    num_heads,
  
  ff_dim =
    ff_dim,
  
  dropout =
    dropout,
  
  num_blocks =
    num_blocks,
  
  input_shape =
    c(
      sequence_length,
      feature_dim
    ),
  
  output_shape =
    c(
      sequence_length,
      attention_dim
    ),
  
  training_sequences =
    n_train,
  
  validation_sequences =
    n_valid,
  
  testing_sequences =
    n_test,
  
  window_size =
    WINDOW_SIZE,
  
  forecast_horizon =
    FORECAST_HORIZON,
  
  train_prop =
    TRAIN_PROP,
  
  valid_prop =
    VALID_PROP,
  
  test_prop =
    TEST_PROP,
  
  yield_names =
    YIELD_NAMES,
  
  factor_names =
    FACTOR_NAMES,
  
  parameter_count =
    parameter_count,
  
  model_file =
    MODEL_FILE,
  
  sequence_data_file =
    SEQUENCE_FILE,
  
  scaling_source =
    "04_sequence_generation.R",
  
  scaling_policy =
    "Training observations only; frozen for validation and test."
  
)

save(
  TransformerConfig,
  file = CONFIG_FILE
)

###############################################################
# 36. SAVE MODEL DIMENSIONS
###############################################################

model_dimensions <-
  data.frame(
    
    Parameter = c(
      
      "Training samples",
      
      "Validation samples",
      
      "Testing samples",
      
      "Sequence length",
      
      "Input feature dimension",
      
      "Attention embedding dimension",
      
      "Head size",
      
      "Number of heads",
      
      "Feed-forward dimension",
      
      "Dropout",
      
      "Transformer blocks",
      
      "Forecast horizon",
      
      "Number of model parameters"
      
    ),
    
    Value = c(
      
      n_train,
      
      n_valid,
      
      n_test,
      
      sequence_length,
      
      feature_dim,
      
      attention_dim,
      
      head_size,
      
      num_heads,
      
      ff_dim,
      
      dropout,
      
      num_blocks,
      
      FORECAST_HORIZON,
      
      parameter_count
      
    ),
    
    stringsAsFactors = FALSE
    
  )

write.csv(
  
  model_dimensions,
  
  DIMENSION_FILE,
  
  row.names = FALSE
  
)

###############################################################
# 37. SAVE POSITIONAL ENCODING
###############################################################

write.csv(
  
  PE_matrix,
  
  PE_FILE,
  
  row.names = FALSE
  
)

###############################################################
# 38. SAVE MODEL VALIDATION RESULTS
###############################################################

validation_results <-
  data.frame(
    
    Check = c(
      
      "X_train is 3-dimensional",
      
      "X_valid is 3-dimensional",
      
      "X_test is 3-dimensional",
      
      "Training data finite",
      
      "Validation data finite",
      
      "Testing data finite",
      
      "Feature scaler valid",
      
      "Target dimensions valid",
      
      "Forward pass successful",
      
      "Output dimension correct",
      
      "Output finite",
      
      "Model file exists",
      
      "Model file non-empty"
      
    ),
    
    Result = c(
      
      length(dim(X_train)) == 3L,
      
      length(dim(X_valid)) == 3L,
      
      length(dim(X_test)) == 3L,
      
      all(is.finite(X_train)),
      
      all(is.finite(X_valid)),
      
      all(is.finite(X_test)),
      
      all(is.finite(feature_center)) &&
        all(is.finite(feature_scale)) &&
        all(feature_scale > 0),
      
      ncol(Y_factor_train) ==
        length(FACTOR_NAMES) &&
        ncol(Y_yield_train) ==
        length(YIELD_NAMES) &&
        ncol(Y_yield_prev_train) ==
        length(YIELD_NAMES),
      
      TRUE,
      
      identical(
        as.integer(output_shape),
        as.integer(expected_output_dim)
      ),
      
      all(is.finite(test_output_array)),
      
      file.exists(MODEL_FILE),
      
      !is.na(model_size) &&
        model_size > 0
      
    ),
    
    stringsAsFactors = FALSE
    
  )

write.csv(
  
  validation_results,
  
  VALIDATION_FILE,
  
  row.names = FALSE
  
)

###############################################################
# 39. FINAL VALIDATION
###############################################################

if (!all(validation_results$Result)) {
  
  stop(
    "One or more Transformer validation checks failed."
  )
}

